def find_clusters_correctly(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    clusters = {}
    for i in range(h):
        for j in range(w):
            color = grid[i][j]
            if color > 0 and not visited[i][j]:
                cluster = []
                stack = [(i, j)]
                while stack:
                    ri, rj = stack.pop()
                    if not visited[ri][rj] and grid[ri][rj] == color:
                        visited[ri][rj] = True
                        cluster.append((ri, rj, color))
                        for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                            ni, nj = ri + di, rj + dj
                            if 0 <= ni < h and 0 <= nj < w and not visited[ni][nj] and grid[ni][nj] == color:
                                stack.append((ni, nj))
                if color not in clusters:
                    clusters[color] = []
                clusters[color].extend(cluster)
    return clusters

